        } catch (Exception e) {
            // ❌ In the log, you will ONLY see the NullPointerException from finally!
            // The critical primary root cause (DatabaseTimeoutException) is PERMANENTLY LOST!
            System.err.println("Caught: " + e.getClass().getSimpleName() + " -> " + e.getMessage());
        }
    }

    public static void processTransaction() {
        DatabaseConnection conn = null;
        try {
            // 1. Primary business failure:
            throw new IllegalStateException("Database query timed out after 3000ms");
        } finally {
            // 2. Secondary cleanup failure:
            conn.close(); // Throws NullPointerException because conn is null!
